  <div class="tob__revs"><div class="tob__revtrack">
    {%- for i in (1..4) -%}{%- for img in review_images -%}
      <img src="https://cdn.shopify.com/s/files/1/0707/4938/9043/files/{{ img }}?width=420" alt="{% if i == 1 %}ביקורת לקוח - חנות השופט{% endif %}" decoding="async"{% if i > 1 %} aria-hidden="true"{% endif %}>
    {%- endfor -%}{%- endfor -%}
