<script type="application/json" id="tob-data-{{ section.id }}">
{
  "min": {{ group_min }},
  "off": {{ group_off | times: 100 }},
  "options": [{%- for o in mp.options_with_values -%}{"name": {{ o.name | json }}, "values": {{ o.values | json }}}{% unless forloop.last %},{% endunless %}{%- endfor -%}],
  "variants": [{%- for v in mp.variants -%}{"id": {{ v.id }}, "o": [{{ v.option1 | json }}, {{ v.option2 | json }}, {{ v.option3 | json }}], "p": {{ v.price }}, "a": {{ v.available | json }}}{% unless forloop.last %},{% endunless %}{%- endfor -%}]
}
</script>
<script>
(function () {
  var root = document.getElementById('tob-{{ section.id }}');
  var dataEl = document.getElementById('tob-data-{{ section.id }}');
  if (!root || !dataEl || root.dataset.ready) return;
  root.dataset.ready = '1';
  var D = JSON.parse(dataEl.textContent);

  /* ---- full width without a horizontal scrollbar ---- */
  function fitWidth() { root.style.setProperty('--tob-vw', document.documentElement.clientWidth + 'px'); }
  fitWidth(); window.addEventListener('resize', fitWidth);

  /* ---- collapse ---- */
  var builder = root.querySelector('.tob__builder');
  var toggle = root.querySelector('[data-toggle]');
  var toggleText = root.querySelector('[data-toggle-text]');
  function setOpen(open, scroll) {
    builder.classList.toggle('is-open', open);
    builder.classList.remove('is-done');
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    toggleText.textContent = open ? 'סגירה' : 'להתחלה';
    if (open) { calc(); setTimeout(function () { builder.classList.add('is-done'); }, 460); }
    if (open && scroll) setTimeout(function () { builder.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 80);
  }
  if (builder.classList.contains('is-open')) builder.classList.add('is-done');
  toggle.addEventListener('click', function () { setOpen(!builder.classList.contains('is-open'), false); });
  root.querySelectorAll('[data-jump]').forEach(function (a) {
    a.addEventListener('click', function (e) { e.preventDefault(); setOpen(true, true); });
  });

  /* ---- builder ---- */
  function idx(word, fallback) {
    for (var i = 0; i < D.options.length; i++) if (D.options[i].name.indexOf(word) > -1) return i;
    return fallback < D.options.length ? fallback : -1;
  }
  var iSize = idx('מידה', 0), iVer = idx('גרסה', 1), iShirt = idx('חולצות', 2);
  var vals = function (i) { return i > -1 ? D.options[i].values : []; };
  var sizes = vals(iSize), versions = vals(iVer), shirts = vals(iShirt);
  var defSize = sizes.indexOf('M') > -1 ? 'M' : sizes[0];

  var rowsEl = root.querySelector('[data-rows]');
  var countEl = root.querySelector('[data-count]');
  var shirtSel = root.querySelector('[data-team-shirts]');
  var prefEl = root.querySelector('[data-team-pref]');
  var goBtn = root.querySelector('[data-go]');
  var errEl = root.querySelector('[data-err]');
  var teaser = root.querySelector('[data-teaser]');
  var rows = [];

  function esc(t) { return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;'); }
  function label(v) { return v.replace(/^גרסת\s*/, '').replace(/\s*\(\+?₪?\d+₪?\)/, ''); }
  function opts(list, sel) {
    return list.map(function (v) { return '<option value="' + esc(v) + '"' + (v === sel ? ' selected' : '') + '>' + esc(label(v)) + '</option>'; }).join('');
  }
  if (shirts.length) { shirtSel.innerHTML = opts(shirts, shirts[0]); } else { shirtSel.closest('label').style.display = 'none'; }

  function findVariant(size, ver) {
    var want = []; want[iSize] = size; want[iVer] = ver; if (iShirt > -1) want[iShirt] = shirtSel.value;
    return D.variants.find(function (v) {
      for (var i = 0; i < D.options.length; i++) if (want[i] !== undefined && v.o[i] !== want[i]) return false;
      return true;
    });
  }
  function money(c) { var n = c / 100; return (n % 1 ? n.toFixed(2) : n.toLocaleString('he-IL')) + '₪'; }
  var BOX = '<svg viewBox="0 0 36 34" aria-hidden="true"><path d="M3 11 18 4l15 7v15l-15 7-15-7z" fill="#c29a6b"/><path d="M3 11l15 7 15-7M18 18v15" stroke="#8a6a44" stroke-width="1.6" fill="none"/></svg>';

  function draw() {
    rowsEl.innerHTML = rows.map(function (r, i) {
      return '<div class="tob__row" data-i="' + i + '">' +
        '<span class="tob__n">' + BOX + '<b>' + (i + 1) + '</b></span>' +
        '<select aria-label="מידה" data-f="size">' + opts(sizes, r.size) + '</select>' +
        '<select aria-label="גרסה" data-f="ver">' + opts(versions, r.ver) + '</select>' +
        '<button type="button" class="tob__del" aria-label="הסרה" data-del>×</button></div>';
    }).join('');
    calc();
  }
  function calc() {
    var n = rows.length, reg = 0, bad = 0;
    rows.forEach(function (r, i) {
      var v = findVariant(r.size, r.ver); r.v = v;
      var el = rowsEl.children[i];
      if (!v || !v.a) { bad++; el && el.classList.add('is-bad'); } else { el && el.classList.remove('is-bad'); }
      if (v) reg += v.p;
    });
    var group = n >= D.min;
    var total = group ? reg - D.off * n : reg;
    root.classList.toggle('is-group', group);
    countEl.textContent = n;
    root.querySelector('[data-bar]').style.width = Math.min(100, n / D.min * 100) + '%';
    var left = D.min - n;
    root.querySelector('[data-msg]').textContent = group ? 'המחיר הקבוצתי פעיל' :
      (left === 1 ? 'עוד חולצה אחת למחיר הקבוצתי' : 'עוד ' + left + ' חולצות למחיר הקבוצתי');
    root.querySelector('[data-n]').textContent = n + ' מיסטרי בוקס';
    root.querySelector('[data-reg]').textContent = group && n ? money(reg) : '';
    root.querySelector('[data-total]').textContent = money(total);
    root.querySelector('[data-save]').textContent = group ? 'חוסכים ' + money(reg - total) : '';
    if (!goBtn.dataset.busy) goBtn.textContent = 'הוסיפו ' + n + ' מיסטרי בוקס לעגלה';
    if (teaser && builder.classList.contains('is-open')) teaser.textContent = n + ' מיסטרי בוקס, ' + money(total) + (group ? ' (חוסכים ' + money(reg - total) + ')' : '');
    errEl.textContent = bad ? (bad === 1 ? 'אחת המידות שבחרתם אזלה. בחרו מידה או גרסה אחרת' : bad + ' מהבחירות אזלו. בחרו מידה או גרסה אחרת') : '';
    goBtn.disabled = n === 0 || bad > 0;
  }
  function setCount(n) {
    n = Math.max(1, Math.min(40, n));
    while (rows.length < n) { var last = rows[rows.length - 1]; rows.push({ size: last ? last.size : defSize, ver: last ? last.ver : versions[0] }); }
    rows.length = n; draw();
  }

  root.addEventListener('click', function (e) {
    var b = e.target.closest('[data-act],[data-del]'); if (!b) return;
    if (b.dataset.act === 'plus') setCount(rows.length + 1);
    else if (b.dataset.act === 'minus') setCount(rows.length - 1);
    else if (b.hasAttribute('data-del') && rows.length > 1) { rows.splice(+b.closest('.tob__row').dataset.i, 1); draw(); }
  });
  rowsEl.addEventListener('input', function (e) {
    var f = e.target.dataset.f; if (!f) return;
    rows[+e.target.closest('.tob__row').dataset.i][f] = e.target.value; calc();
  });
  shirtSel.addEventListener('change', calc);

  goBtn.addEventListener('click', function () {
    var pref = prefEl.value.trim(), map = {};
    rows.forEach(function (r) {
      var props = {}; if (pref) props['העדפות למיסטרי בוקס'] = pref;
      var key = r.v.id + '|' + JSON.stringify(props);
      if (map[key]) map[key].quantity++; else map[key] = { id: r.v.id, quantity: 1, properties: props };
    });
    goBtn.disabled = true; goBtn.dataset.busy = '1'; goBtn.textContent = 'מוסיפים לעגלה...'; errEl.textContent = '';
    fetch('/cart/add.js', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({ items: Object.keys(map).map(function (k) { return map[k]; }) }) })
      .then(function (r) { return r.json().then(function (j) { if (!r.ok) throw j; return j; }); })
      .then(function () { window.location.href = '/cart'; })
      .catch(function (j) {
        errEl.textContent = (j && j.description) ? j.description : 'משהו השתבש. נסו שוב או דברו איתנו בוואטסאפ';
        goBtn.disabled = false; delete goBtn.dataset.busy; calc();
      });
  });

  setCount(D.min);
})();
</script>
{%- endif -%}
